import{_ as t,o,c as r,a0 as a}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"Momus-MCP — Technical Specification","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),s={name:"README.md"};function i(d,e,n,c,l,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="momus-mcp-—-technical-specification" tabindex="-1">Momus-MCP — Technical Specification <a class="header-anchor" href="#momus-mcp-—-technical-specification" aria-label="Permalink to &quot;Momus-MCP — Technical Specification&quot;">​</a></h1><p><strong>Momus-MCP</strong> is a production-ready, open-source Model Context Protocol (MCP) server that acts as an unsparing, deterministic, local-first <strong>mock and test integrity auditor</strong> for coding agents. Named after Momus, the classical god of sharp critique and fault-finding, it exists to stop &quot;false-green&quot; test suites — suites that pass while proving nothing.</p><p>This directory is the authoritative specification. It is written so that <strong>agents and engineers can be pointed at it</strong> and implement the system without further clarification. Every module, interface, rule, schema, and phase below is normative unless explicitly marked <em>non-normative</em>.</p><hr><h2 id="how-to-read-this-spec" tabindex="-1">How to read this spec <a class="header-anchor" href="#how-to-read-this-spec" aria-label="Permalink to &quot;How to read this spec&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Contents</th><th>Read when</th></tr></thead><tbody><tr><td><a href="./01-executive-summary.html"><code>01-executive-summary.md</code></a></td><td>Vision, problem statement, design principles, hard constraints, threat model, scope</td><td>Before anything else</td></tr><tr><td><a href="./02-architecture.html"><code>02-architecture.md</code></a></td><td>Parsing strategy, normalized IR, symbol index, mock identification catalog, configuration</td><td>Implementing the engine</td></tr><tr><td><a href="./03-analysis-algorithms.html"><code>03-analysis-algorithms.md</code></a></td><td>Rule catalog, tautology &amp; drift algorithms, suppression semantics, false-positive policy</td><td>Implementing rules</td></tr><tr><td><a href="./04-mcp-tool-definitions.html"><code>04-mcp-tool-definitions.md</code></a></td><td>Full tool manifest, JSON Schemas, example payloads, agent usage protocol</td><td>Implementing the MCP server</td></tr><tr><td><a href="./05-output-format.html"><code>05-output-format.md</code></a></td><td>Issue line grammar, Markdown/JSON report schemas, token budget contract</td><td>Implementing formatters</td></tr><tr><td><a href="./06-repository-layout.html"><code>06-repository-layout.md</code></a></td><td>Monorepo structure, tech stack, CI/CD, test strategy, release process</td><td>Scaffolding the repo</td></tr><tr><td><a href="./07-roadmap.html"><code>07-roadmap.md</code></a></td><td>Phased implementation plan with acceptance criteria</td><td>Scheduling work</td></tr><tr><td><a href="./09-validation-report.html"><code>09-validation-report.md</code></a></td><td>Spike results: what was experimentally proven buildable, and the spec deltas it forced</td><td>Before Phase 1, and whenever a spec section seems risky</td></tr><tr><td><a href="./10-build-plan.html"><code>10-build-plan.md</code></a></td><td><strong>The achievable goal</strong>: what is already built &amp; verified, and the sequenced plan to v0.1 → Phase 4</td><td>Starting work today</td></tr><tr><td><a href="./11-real-world-findings.html"><code>11-real-world-findings.md</code></a></td><td>Live record of Momus findings + Momus bugs on the real Chaos-MCP / Knossos-MCP repos</td><td>Validating against real codebases</td></tr></tbody></table><p><strong>Reading order for a new contributor:</strong> <code>01</code> → <code>02</code> → <code>03</code> → <code>06</code> (build the engine), then <code>04</code> → <code>05</code> (expose it), then <code>10</code> → <code>07</code> (what&#39;s done, what&#39;s next).</p><hr><h2 id="canonical-facts-defined-once-here-referenced-everywhere" tabindex="-1">Canonical facts (defined once here, referenced everywhere) <a class="header-anchor" href="#canonical-facts-defined-once-here-referenced-everywhere" aria-label="Permalink to &quot;Canonical facts (defined once here, referenced everywhere)&quot;">​</a></h2><ul><li><strong>Project name:</strong> Momus-MCP · binary/CLI: <code>momus</code> · npm scope: <code>@momus/*</code> · MCP server name: <code>momus-mcp</code></li><li><strong>Why &quot;Momus&quot;:</strong> the ancient Greek spirit and personification of satire, mockery, blame, and harsh criticism — the ultimate critic among the deities; his name means &quot;blame&quot; or &quot;censure&quot;. Apt both because the tool is an unsparing critic of test suites and because its subject is <em>mock</em> objects.</li><li><strong>Language of implementation:</strong> TypeScript (Node.js ≥ 20, ESM). Rationale in §2 of <code>01-executive-summary.md</code>.</li><li><strong>Package manager:</strong> <code>npm</code> workspaces (confirmed in this environment; pnpm unconfirmed — swap is drop-in). <strong>Test runner:</strong> <code>vitest</code>. <strong>License:</strong> MIT.</li><li><strong>Phase-1 languages/frameworks:</strong> TypeScript/JavaScript with Vitest and Jest. <strong>Phase-2:</strong> PHP with PHPUnit and Pest.</li><li><strong>The four primary MCP tools:</strong> <code>audit_test_fidelity</code>, <code>detect_tautological_assertions</code>, <code>verify_mock_drift</code>, <code>synthesize_mock_contract</code> — plus the supporting tool <code>list_rules</code>.</li><li><strong>Rule IDs:</strong> <code>TAUT-00x</code> (tautological assertions), <code>DRIFT-00x</code> (mock contract drift), <code>MOCK-00x</code> (mock hygiene). The complete catalog lives in <code>03-analysis-algorithms.md</code> §3.3.</li><li><strong>Hard constraints:</strong> read-only tools, no network egress, no execution of user code, no destructive writes without explicit confirmation, every issue rendered in <strong>&lt; 100 tokens</strong>.</li></ul><hr><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><strong>False-green</strong></td><td>A test suite that passes while failing to verify the behavior it claims to verify (over-mocked, tautological, or drifted).</td></tr><tr><td><strong>Tautological assertion</strong></td><td>An assertion that cannot fail — it only re-asserts what was already configured or compared against itself.</td></tr><tr><td><strong>Mock drift</strong></td><td>A test double whose shape (members, signatures, types) no longer matches the production symbol it doubles.</td></tr><tr><td><strong>Contract fidelity</strong></td><td>The degree to which a test double matches the production interface it replaces.</td></tr><tr><td><strong>Symbol index</strong></td><td>The in-memory/embedded graph of production symbols (classes, interfaces, methods, types) built from ASTs.</td></tr><tr><td><strong>IR</strong></td><td>Intermediate Representation — the language-neutral module model emitted by parser plugins.</td></tr><tr><td><strong>SUT</strong></td><td>System Under Test — the production code a test file is meant to exercise.</td></tr><tr><td><strong>Suppression</strong></td><td>An explicit, auditable opt-out (<code>// @momus-ignore</code> family) for intentional stubbing.</td></tr><tr><td><strong>Mock saturation</strong></td><td>A heuristic measure of over-mocking: the share of a test&#39;s dependencies that are test doubles.</td></tr></tbody></table><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><ul><li>[x] <strong>Pre-implementation spike</strong> (<code>09-validation-report.md</code>) — all experiments green, spec deltas applied</li><li>[x] <strong>Phase 1 implementation</strong> — built and verified: <code>@momus/core</code> (rules engine, suppression, formatters), <code>@momus/parser-typescript</code> (custom-host program, mock detection, dataflow), <code>@momus/mcp-server</code> (5 tools), <code>@momus/cli</code> (audit/drift/contract/rules/serve/init/doctor). 207 tests green, self-audit clean, CI workflow in place. See <code>10-build-plan.md</code>.</li><li>[x] <strong>v0.1 packaging</strong> (Step 1 of <code>10-build-plan.md</code>) — README, npm pack dry-run, <code>npx momus</code> verification</li><li>[x] Phase 2 (PHP support) — complete: PHPUnit/Mockery/Pest mocks (incl. closure-form, <code>getMockForAbstractClass</code>, <code>setUp</code> property mocks, docblock typing, DRIFT-003/004, Composer PSR-4 + classmap resolution); see <code>10-build-plan.md</code> Step 3</li><li>[x] Phase 3 (git-diff hooks + CLI companion) — <code>precommit</code>, <code>audit|drift --git-diff</code>, DRIFT-006, MCP git-diff scope, <code>hook</code>, <code>serve --transport http</code>, <code>serve --watch</code> (chokidar), <code>annotate</code> (JSONL), and <code>audit --fix</code> (DRIFT-001 rename fix; TAUT-* are semantic and intentionally descriptive-only).</li><li>[x] Test-coverage tooling — <code>npm run test:coverage</code> (v8) with floors 80% statements/lines, 75% branches, 90% functions; currently ~84% statements / ~82% branches across library modules.</li><li>[x] Persistent IR cache — <code>better-sqlite3</code> at <code>.momus/cache/</code>, keyed by file content hash + workspace digest (advisory, deterministic); ESLint + Prettier authoring gates (<code>lint</code>/<code>format</code> scripts) shipped.</li><li>[ ] Phase 4 (CI action + registry publishing) — action + <code>annotate-pr</code> + <code>release-please</code> shipped in-repo; npm/MCP publishing pending credentials</li></ul><p>See <a href="./10-build-plan.html"><code>10-build-plan.md</code></a> for the achievable goal and sequenced work, and <a href="./07-roadmap.html"><code>07-roadmap.md</code></a> for the original phased plan.</p>',17)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
